354: // ResolveAlias follows the alias chain to return the final target scope.
355: func (idx *Index) ResolveAlias(ctx context.Context, scope string) (string, error) {
356: 	current := strings.TrimSpace(scope)
357: 	if current == "" {
358: 		return "", nil
359: 	}
360: 
361: 	maxDepth := 10
362: 	visited := make(map[string]bool)
363: 
364: 	for depth := 0; depth < maxDepth; depth++ {
365: 		var next string
366: 		err := idx.db.QueryRowContext(ctx,
367: 			"SELECT new_scope FROM aliases WHERE old_scope = ? ORDER BY created_at DESC LIMIT 1",
368: 			current).Scan(&next)
369: 		if err != nil {
370: 			if errors.Is(err, sql.ErrNoRows) {
371: 				break
372: 			}
373: 			return "", fmt.Errorf("resolving alias %s: %w", current, err)
374: 		}
375: 		next = strings.TrimSpace(next)
376: 		if next == "" || next == current || visited[next] {
377: 			break
378: 		}
379: 		visited[current] = true
380: 		current = next
381: 	}
382: 	return current, nil
383: }
